  def arrow(x1,y1,x2,y2):
   c.setStrokeColor(BLUE);c.setFillColor(BLUE);c.setLineWidth(1.3);c.line(x1,y1,x2,y2);a=math.atan2(y2-y1,x2-x1);s=5;pt=c.beginPath();pt.moveTo(x2,y2);pt.lineTo(x2-s*math.cos(a-.5),y2-s*math.sin(a-.5));pt.lineTo(x2-s*math.cos(a+.5),y2-s*math.sin(a+.5));pt.close();c.drawPath(pt,fill=1,stroke=0)
