   steps=[('NUERS active','Destination rehearsal is read-only'),('Freeze and checkpoint','Pause intake and mutating/delivery jobs'),('Final extract + reconciliation','Catch late records and unresolved outcomes'),('Destination accepted','Enable one writer; revoke old write access'),('NUERS retained archive','Authorized retrieval and holds continue')]
