page('13 | Operational templates','Handover and migration acceptance record','Record received, verified and accepted as separate states.',
 table(['Control','Evidence / sign-off field'],[
 ['Package receipt','Package ID/revision; source release; scope; encrypted bytes/hash; received time; recipient identity; custody reference.'],['Integrity','Header/schema valid; terminal manifest present; table counts/hashes match; package signature/channel verified; decryptability confirmed.'],['Import','Importer/mapping version; target tenant; started/completed time; inserted/mapped/rejected counts; idempotent-repeat result.'],['Business validation','Transactions/receipts/items; financial/tax/discount/fee totals; wallet; source IDs; status; Live/Sandbox separation.'],['Document validation','File/version completeness; plaintext hashes; sample rendering; original/copy distinction; branding context.'],['Provenance / access','Source audit preserved; mapped lineage; required archive access; target permissions and confidentiality tests.'],['Exceptions','Exception ID; affected records/value; risk; owner; resolution date; explicit acceptance or rejection.'],['Cutover decision','Go/no-go; merchant owner; receiving owner; NUERS exit manager; finance/security reviewers; timestamp.'],['Closure prerequisites','Settlement decision; retained-copy register; revocation tests; disposal approvals; support owner.']],[.3,.7]),
 note('Acceptance wording: "The undersigned accept package [ID/revision] for the specified scope subject only to the recorded exceptions. This confirms agreed migration validation; it does not certify regulatory approval or authorize deletion of retained records."'))

page('13 | Operational templates','Retention and disposal record','A completion record must identify what remains and why.',
 table(['Field','Required evidence'],[
 ['Authority','Case/change ID; owner approval; applicable retention/hold review; eligibility decision and reviewer.'],['Asset scope','Exact tenant/dataset/file versions; active/staging/replica/backup locations; package and record identifiers.'],['Retained exceptions','Basis; hold reference; archive owner; access route; review/expiry trigger; dependency on retained keys.'],['Disposal method','Logical deletion, media sanitization, provider disposal or eligible cryptographic erasure; tool/service/version and scope limitations.'],['Execution','Operator; start/end UTC/PHT; job/output reference; failures/retries; affected asset count.'],['Verification','Independent verifier; read/access tests; provider evidence; logs and hashes where appropriate.'],['Backups','Residual backup sets; scheduled expiry; restrictions; disposition ledger to apply after any restoration.'],['Certification','Authorized sign-off stating completed scope and exceptions; no claim of physical sanitization without supporting evidence.']],[.31,.69]),
 p('Suggested closure statement: "The specified eligible copies were disposed of using the recorded method on [date]. Records listed in the retained-copy register remain protected for the stated purpose/basis. This statement does not cover unlisted recipient copies or unverified provider media."'),
 note('This is a reusable record template. No real NUERS records were deleted, no hold was released and no disposal certificate was issued by preparing this PDF.'))

page('14 | Readiness and validation','Risk register and completion priorities','Close product and operational gaps before promising complete portability.',
 table(['Risk / gap','Required mitigation and accountable role'],[
 ['Missing assets/new workflows','Compare every used feature with the export allowlist; supplement files, Sandbox, branding and current delivery records. Data custodian + application lead.'],['Ciphertext without usable content','Inventory remaining encrypted fields; produce authorized tenant-scoped usable supplements without shared keys. Security + export operator.'],['Inconsistent concurrent export','Prove engine snapshot/isolation and object boundary or use a controlled freeze/final full extract. Database + application leads.'],['Unsigned / incomplete stream','Require terminal manifest, exact hashes and recipient-authenticated packaging. Export operator + receiver.'],['No validated importer','Build and rehearse destination mapping; test duplicates, money, document rendering and failure cases. Receiving system owner.'],['Audit subset not full-chain proof','Preserve original hashes and provide scoped verification context/attestation without foreign-tenant disclosure. Assurance + security.'],['Access or settlement dispute','Maintain verified assisted retrieval and clear settlement/retention decisions. Service owner + finance/legal.'],['Premature deletion','Separate retention/hold approval, archive acceptance and disposal verification. Data owner + independent reviewer.']],[.36,.64]),
 note('Status at issue: these are explicit readiness requirements, not completed remediation claims. Assign dates and evidence in the actual exit project; document any accepted residual risk.'))

page('14 | Readiness and validation','Validation evidence and source baseline','Limited isolated test evidence supports the current export description.',
 p('Three existing portability-related feature tests were executed on 19 October 2026 using isolated in-memory SQLite fixtures. Result: <b>3 tests, 27 assertions passed</b> under PHPUnit 11.5.55 / PHP 8.5.9, in 0.695 seconds. No production export or third-party migration was performed.'),
 table(['Test / source','What it supports'],[
 ['MerchantWalletTest portability case','Owned wallet data appears; other tenant access is rejected; regulator output excludes wallet entries in that tested scenario.'],['MerchantCustomerTest portability case','Usable customer profile/history appears; selected identity hash is excluded; foreign tenant access is rejected.'],['DurableWorkflowTest portability case','Scoped new evidence export and independent hold-release behavior in the tested fixture.'],['TenantPortability service','Current table allowlist, relational scoping and selected column exclusions.'],['TenantPortabilityController','NDJSON header/record/manifest behavior, selected decryption, wallet entitlement and pre-stream audit event.'],['ApiAccess / ApiBoundary / routes','Human session and role/tenant access, applicable MFA, suspended-write restrictions and route throttle.']],[.38,.62]),
 p('The tests are not a complete column-level confidentiality audit, large-volume benchmark, all-feature inventory or cross-system round-trip test. Production engine isolation, large exports, file supplementation, recipient transfer and destination acceptance require separate evidence.'),
 note('Selected source SHA-256 values, the test execution record and PDF quality checks are retained with this plan\'s supporting files. Code review does not prove that the same release is deployed online.'))

page('15 | References and approval','References, approval and revision history','Maintain the plan with each material data-model or provider change.',
 p('<b>[R1] National Privacy Commission - Republic Act No. 10173.</b> Sections 18 and 21 provide relevant portability/accountability context. Apply the actual scope and lawful basis through qualified review.<br/><link href="https://privacy.gov.ph/data-privacy-act-/" color="#0056d6">privacy.gov.ph/data-privacy-act-/</link>'),
 p('<b>[R2] National Privacy Commission - Right to data portability.</b> Guidance on the personal-data right and its scope.<br/><link href="https://privacy.gov.ph/right-to-data-portability/" color="#0056d6">privacy.gov.ph/right-to-data-portability/</link>'),
 p('<b>[R3] NIST SP 800-88 Rev. 2 - Guidelines for Media Sanitization.</b> Reference for the disposal program; not a NUERS sanitization certification.<br/><link href="https://csrc.nist.gov/pubs/sp/800/88/r2/final" color="#0056d6">csrc.nist.gov/pubs/sp/800/88/r2/final</link>'),
 p('<b>Internal alignment:</b> NUERS Technical Specifications and System Manual 1.0.0; Backup Procedure and Disaster Recovery Plan 1.0.0; reviewed portability/governance source and tests. The supplied ESP presentation lists an exit/migration/data-portability plan as a documentary item; that source alone is not proof of current accreditation or full compliance.'),
 h('Approval and maintenance'),
 p('Approval pending: NUERS service owner, data/security/privacy owner, operations lead and finance/legal reviewers as relevant. Each executed migration also requires the merchant and recipient\'s scope/acceptance approval. Review at least annually and after significant schema, key, storage, provider, legal or service changes.'),
 p('<b>Edition 1.0 | 19 October 2026:</b> Initial plan for NUERS software 1.0.0. Includes implemented export behavior, explicit gaps, proposed migration/closure procedures, operational forms and limited isolated test evidence.'),
 note('Official references checked on 19 October 2026. Proposed timelines and procedures are not contractual or statutory guarantees. No destination migration, accreditation, settlement or secure-disposal certification is asserted.'))

